#!/usr/bin/env node
// Record the TypeScript half of suites/opentelemetry-span-attributes/cases.json.
//
// The reference's half is generated by tools/generate-otel-span-attributes.php
// and the Python half by tools/record_otel_span_attributes.py. This suite is a
// `security-corpus`, so there is no `expect` to compare against: each row
// records what every language PRODUCED and the three answers are the finding.
// That only means anything if every column was EXECUTED, so this runs the port
// rather than transcribing a reading of its source.
//
//   node tools/record-otel-span-attributes.mjs
//   node tools/record-otel-span-attributes.mjs --check
//
// WHY THIS DID NOT EXIST UNTIL NOW, and what its absence cost. The suite had a
// PHP generator and no recorder for the other two columns, so a new row's `ts`
// and `py` spans had to be written BY HAND — producing a corpus that asserts
// what its author believed the ports do. Registered as G-62.
//
// The cost was not hypothetical. `AdvertisedTool`'s digest shipped in
// particle-academy/prism v0.124.0 hashing an empty parameter map as `[]`, a
// PHP-ism no other language reproduces, so the attribute that exists to be
// compared ACROSS services was not comparable across services. Every test
// asserted PHP against PHP and the release audit asked a different question.
// It surfaced while this file was being written, before a line of it ran.
//
// It imports the port's BUILT output from the sibling checkout in the `.agi`
// envelope, the same way the PHP generator reaches for the reference's
// autoloader. That is a GENERATOR's licence and not a loader's — loaders must
// find fixtures inside their own published artifact, and nothing here is
// shipped. `npm run build` in prism-opentelemetry-ts first: this reads dist/,
// because dist/ is what a consumer gets.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const check = process.argv.includes('--check');
const dist = resolve(
  process.env.PRISM_OTEL_TS_DIST ?? join(root, '..', 'prism-opentelemetry-ts', 'dist'),
);

if (!existsSync(join(dist, 'index.js'))) {
  console.error(
    `No prism-opentelemetry-ts build at ${dist}. Run \`npm run build\` there, or set PRISM_OTEL_TS_DIST.`,
  );
  process.exit(3);
}

const port = await import(pathToFileURL(join(dist, 'index.js')).href);
const { SpanStore, TelemetrySubscriber } = port;

/**
 * The port's own digest helper, or nothing.
 *
 * Read off the module rather than reimplemented here. A recorder that computed
 * the digest itself would record agreement between THIS FILE and the reference
 * while the port computed something else entirely — the vacuous-pass shape this
 * repository exists to prevent. If the port exports no helper, the column
 * records the absence, the row disagrees, and that is the honest answer.
 */
const advertisedToolDigest = port.advertisedToolDigest;

const casesPath = join(root, 'suites', 'opentelemetry-span-attributes', 'cases.json');
const document = JSON.parse(readFileSync(casesPath, 'utf8'));

/** A tracer that records rather than exports — no SDK, no collector, no clock. */
function record(entry) {
  const spans = [];

  const tracer = {
    startSpan(name) {
      const recorded = { name, status: 'unset', attributes: {} };
      spans.push(recorded);

      return {
        setAttribute(key, value) {
          recorded.attributes[key] = value;
        },
        setStatus(status) {
          recorded.status = status.code;
        },
        recordException() {},
        end() {},
      };
    },
  };

  const g = entry.generation;
  const subscriber = new TelemetrySubscriber(tracer, new SpanStore(), {
    maxContentLength: entry.max_content_length,
    captureContent: entry.capture_content,
    now: () => 0,
  });

  subscriber.onGenerationStarted(
    {
      traceId: entry.id,
      operation: g.operation,
      provider: g.provider,
      model: g.model,
      sessionId: g.session_id,
      userId: g.user_id,
    },
    g.input ?? undefined,
    // Absent stays absent: a row with no `tools` key must produce a span with
    // no tool attributes, which is a different assertion from a row with an
    // empty list. `?? undefined` keeps those two distinguishable.
    g.tools === undefined || g.tools === null ? undefined : g.tools.map(advertisedTool),
  );

  subscriber.onGenerationCompleted(entry.id, {
    finishReason: g.finish_reason,
    rateLimits: g.rate_limits === null ? undefined : g.rate_limits.map(rateLimit),
    usage: g.usage === null ? undefined : usage(g.usage),
    output: g.output ?? undefined,
  });

  if (spans.length !== 1) {
    console.error(`${entry.id}: expected exactly one root span, got ${spans.length}.`);
    process.exit(4);
  }

  const span = spans[0];

  return {
    name: span.name,
    status: span.status,
    attributes: Object.fromEntries(
      Object.entries(span.attributes).sort(([a], [b]) => (a < b ? -1 : 1)),
    ),
  };
}

/**
 * A corpus tool as the port takes one.
 *
 * THE DIGEST IS COMPUTED, NOT COPIED. A row supplies the tool's DECLARATION and
 * each language fingerprints it, which is the only way the corpus can ask
 * whether three languages agree about the digest — the question the attribute
 * exists for. Handing every column the same precomputed string would pin the
 * fixture instead of the code.
 */
function advertisedTool(tool) {
  return {
    name: tool.name,
    digest: digestOf(tool),
    description: tool.description ?? undefined,
    parameters: tool.parameters ?? undefined,
  };
}

function digestOf(tool) {
  return typeof advertisedToolDigest === 'function'
    ? advertisedToolDigest({
        name: tool.name,
        description: tool.description ?? '',
        parameters: tool.parameters ?? {},
      })
    : undefined;
}

/**
 * A corpus usage record as the port takes one.
 *
 * The cache and reasoning fields are optional in the fixture because the rows
 * that predate them do not carry the keys, and `undefined` is how the port is
 * told a provider reported nothing — which is NOT the same as zero.
 */
function usage(entry) {
  return {
    promptTokens: entry.prompt_tokens,
    completionTokens: entry.completion_tokens,
    cacheReadInputTokens: entry.cache_read_input_tokens ?? undefined,
    cacheWriteInputTokens: entry.cache_write_input_tokens ?? undefined,
    thoughtTokens: entry.thought_tokens ?? undefined,
    cost: entry.cost,
  };
}

/**
 * A corpus bucket as the port takes one.
 *
 * `resets_at` is parsed HERE and not in the port: the port is handed an
 * instant, so nothing in this comparison depends on three languages agreeing
 * about how to render or re-render a date.
 */
function rateLimit(entry) {
  return {
    name: entry.name,
    limit: entry.limit,
    remaining: entry.remaining,
    resetsAt: entry.resets_at === null ? null : new Date(entry.resets_at),
  };
}

/**
 * Where two recorded spans differ, by field name.
 *
 * Attribute KEYS present in one column and absent in the other count, which is
 * the case that matters most here: a port emitting no digest at all is a
 * disagreement, and a comparison that only looked at shared keys would call it
 * agreement.
 */
function differences(reference, other) {
  const fields = [];

  if (reference.name !== other.name) fields.push('span name');
  if (reference.status !== other.status) fields.push('span status');

  const keys = new Set([...Object.keys(reference.attributes), ...Object.keys(other.attributes)]);

  for (const key of [...keys].sort()) {
    const a = JSON.stringify(reference.attributes[key] ?? null);
    const b = JSON.stringify(other.attributes[key] ?? null);

    if (a !== b) fields.push(key);
  }

  return fields;
}

const stale = [];

for (const entry of document.cases) {
  const produced = record(entry);
  const recorded = entry.spans.ts ?? null;

  if (JSON.stringify(recorded) !== JSON.stringify(produced)) {
    stale.push(
      `${entry.id}: recorded ${JSON.stringify(recorded)}, prism-opentelemetry-ts produces ${JSON.stringify(produced)}`,
    );
  }

  entry.spans.ts = produced;
}

// DERIVED from whichever columns exist, never asserted. A row cannot be marked
// as agreeing by an editor who wanted it to, and `disagrees_on` cannot quietly
// omit a field that started differing — each runner asserts that nothing
// outside the register's named set appears in it, so a new divergence fails a
// test instead of joining a row that was already red.
for (const entry of document.cases) {
  const reference = entry.spans.php ?? null;
  const others = Object.entries(entry.spans).filter(([lang, span]) => lang !== 'php' && span);

  if (!reference || others.length === 0) {
    entry.agrees = false;
    continue;
  }

  const fields = new Set();

  for (const [, span] of others) {
    for (const field of differences(reference, span)) fields.add(field);
  }

  entry.agrees = fields.size === 0;
  entry.disagrees_on = [...fields].sort();
}

if (check) {
  if (stale.length > 0) {
    console.error(
      `Stale TypeScript spans in opentelemetry-span-attributes:\n  ${stale.join('\n  ')}`,
    );
    process.exit(1);
  }

  console.error('opentelemetry-span-attributes: every TypeScript row matches the port.');
  process.exit(0);
}

writeFileSync(casesPath, `${JSON.stringify(document, null, 4)}\n`);

console.error(
  stale.length === 0
    ? 'opentelemetry-span-attributes: no change.'
    : `opentelemetry-span-attributes: rewrote ${stale.length} TypeScript row(s).\n  ${stale.join('\n  ')}`,
);
